create table trust_source_verification_snapshots(id uuid not null,tenant_id uuid not null,rules_version text not null check(rules_version='trust-source-verification.v1'),blueprint_id uuid not null,input_sha256 char(64) not null,status text not null check(status='complete_with_gaps'),fact_level text not null check(fact_level='F2'),target_count integer not null check(target_count=4),independently_verified_count integer not null check(independently_verified_count>=0),self_asserted_count integer not null check(self_asserted_count>=0),blocked_count integer not null check(blocked_count>=0),results jsonb not null check(jsonb_typeof(results)='array'),resolved_evidence_tasks jsonb not null check(jsonb_typeof(resolved_evidence_tasks)='array'),remaining_evidence_tasks jsonb not null check(jsonb_typeof(remaining_evidence_tasks)='array'),publication_authorized boolean not null check(publication_authorized=false),created_at timestamptz not null,primary key(tenant_id,id),unique(tenant_id,input_sha256),foreign key(tenant_id,blueprint_id) references trust_evidence_blueprints(tenant_id,id));
create trigger trust_source_verification_snapshots_append_only before update or delete on trust_source_verification_snapshots for each row execute function reject_immutable_mutation();create trigger trust_source_verification_snapshots_no_truncate before truncate on trust_source_verification_snapshots for each statement execute function reject_immutable_mutation();alter table trust_source_verification_snapshots enable row level security;alter table trust_source_verification_snapshots force row level security;create policy trust_source_verification_snapshots_tenant_isolation on trust_source_verification_snapshots using(tenant_id=nullif(current_setting('app.tenant_id',true),'')::uuid) with check(tenant_id=nullif(current_setting('app.tenant_id',true),'')::uuid);
